"""Additional distinct source decisions; consumed by author.py, no execution backend."""
def extend(add,E,A,Q,R,U,V):
    # Sixteen public API contracts, separate facts rather than query translations.
    add('exact/API','parameter-array','route-params','How does app.param accept an array of parameter names?','It iterates names, recursively registers each with the same callback, then returns the app; single names are delegated to router.param.',[(A,322,336,'param')])
    add('exact/API','method-all','all-methods','What does app.all register for a path?','It obtains one route, slices callback arguments, and applies those callbacks to each lowercased Node HTTP method on that route.',[(A,494,504,'all')])
    add('exact/API','range-missing','range','What does req.range return when Range is missing, and how are options forwarded?','It returns undefined when no Range header exists; otherwise parseRange(size, range, options) receives the original options.',[(Q,214,218,'range')])
    add('exact/API','request-is-varargs','request-mime','How does req.is normalize variadic type arguments?','An array is used directly; other inputs are copied from arguments into an array passed to typeis(this, arr).',[(Q,269,282,'is')])
    add('exact/API','request-path','request-path','What request property returns only the parsed pathname of req.url?','The path getter returns parse(this).pathname.',[(Q,403,405,'path')])
    add('exact/API','xhr-recognition','xhr','Which header and comparison determine req.xhr?','It reads X-Requested-With, defaults to an empty string, lowercases it, and compares with xmlhttprequest.',[(Q,508,511,'xhr')])
    add('exact/API','attachment-basename','attachment','How does res.attachment choose filename and content type?','For a supplied filename it takes basename, derives type from its extension when nonempty, and sets Content-Disposition through contentDisposition.create.',[(R,608,617,'attachment')])
    add('exact/API','sendstatus-fallback','response-status','How does res.sendStatus choose the body for an unknown but valid HTTP status?','It uses statuses.message[statusCode] or String(statusCode), sets status and text type, then sends that body.',[(R,325,332,'sendStatus')])
    add('exact/API','type-fallback','response-mime','What does res.type do for an unmapped extension?','Without a slash it calls mime.contentType(type), falling back to application/octet-stream; a slash-containing type is passed through to set.',[(R,507,514,'contentType')])
    add('exact/API','header-append','response-headers','How does res.append combine an existing scalar header and a new array value?','It concatenates [prev] with the supplied array; existing arrays use prev.concat(val), and two scalars become [prev,val], then set is called.',[(R,634,647,'append')])
    add('exact/API','location-encoding','redirect','Which response API encodes a redirect location without constructing a response body?','res.location sets Location to encodeUrl(url) and returns the response.',[(R,796,798,'location')])
    add('exact/API','subapp-absolute-path','mount-path','How does app.path derive the full path for a nested mounted app?','It recursively concatenates parent.path() and mountpath; a top-level app returns an empty string.',[(A,399,403,'path')])
    add('exact/API','settings-toggle','setting-toggle','Which application methods write true or false settings and how do enabled/disabled read them?','enable and disable call set with true/false; enabled coerces set(setting) to Boolean and disabled negates it.',[(A,420,422,'enabled'),(A,439,441,'disabled'),(A,451,453,'enable'),(A,463,465,'disable')])
    add('exact/API','normalize-accept-types','mime-normalization','How are Accept type strings with parameters and extension shorthand normalized?','normalizeType delegates slash-containing values to acceptParams; extensions use mime.lookup or application/octet-stream with empty params; normalizeTypes maps it over an array.',[(U,61,65,'normalizeType'),(U,75,77,'normalizeTypes')])
    add('exact/API','charset-rewrite','charset','What does setCharset return when type or charset is missing?','It returns type unchanged; otherwise it parses the type, overwrites parameters.charset, and formats it.',[(U,225,237,'setCharset')])
    add('exact/API','accept-language-call','accept-negotiation','What receiver and arguments does req.acceptsLanguages use when delegating language negotiation?','It obtains accepts(this) and calls languages(...languages) on that returned object.',[(Q,185,187,'acceptsLanguages')])
    # Sixteen independent behavioral decisions.
    add('behavior','head-body-suppression','send-head','How does res.send finish a HEAD response after preparing headers?','It calls end() without a chunk for HEAD; other methods pass chunk and encoding.',[(R,213,222,'send')])
    add('behavior','empty-status-headers','send-empty-status','What happens to entity and transfer headers when res.send uses status 204 or 304?','Content-Type, Content-Length and Transfer-Encoding are removed and the chunk is set to an empty string.',[(R,198,204,'send')])
    add('behavior','reset-content-205','send-reset','How is a 205 response body handled by res.send?','It sets Content-Length to 0, removes Transfer-Encoding and empties the chunk.',[(R,206,211,'send')])
    add('behavior','typed-array-send','send-body-dispatch','Does res.send route ArrayBuffer views through res.json?','No; ArrayBuffer.isView selects binary handling and sets bin type only when absent; ordinary non-null objects go to json.',[(R,134,164,'send')])
    add('behavior','links-many-targets','links','How does res.links encode several URLs for one relation when a Link header already exists?','It preserves the old header with a comma separator, maps each URL to <URL>; rel="relation", and joins entries with commas.',[(R,98,114,'links')])
    add('behavior','download-header-protection','download','Can options.headers override the attachment Content-Disposition generated by res.download?','No; the merge skips every key whose lowercase is content-disposition, while copying other keys.',[(R,461,483,'download')])
    add('behavior','format-default-exclusion','format','How does res.format treat the default property during negotiation and fallback?','default is excluded from offered keys; negotiated key runs its callback, otherwise default runs if supplied, else next receives a 406 error with normalized types.',[(R,573,598,'format')])
    add('behavior','cookie-maxage-conversion','cookies','How does res.cookie convert millisecond maxAge and object values?','Object values receive j: plus JSON.stringify. Numeric maxAge sets expires from Date.now()+maxAge and maxAge to floor(milliseconds/1000); missing path defaults to /.',[(R,747,783,'cookie')])
    add('behavior','proxy-ips-order','proxy-ips','How does req.ips order proxy addresses and remove the socket address?','It uses proxyaddr.all with the trust function, reverses the result and pops the socket address.',[(Q,357,367,'ips')])
    add('behavior','ipv6-hostname-port','hostname','How does req.hostname avoid confusing an IPv6 literal colon with the port separator?','For bracket-leading host it starts the colon search after the closing bracket; otherwise it starts at 0, removing only a port suffix.',[(Q,444,459,'hostname')])
    add('behavior','forwarded-host-first','proxy-host','Which X-Forwarded-Host value does req.host choose and when does it ignore that header?','Without a header or trust for socket hop 0, Host is used. For a trusted comma list it takes the first value with trimEnd, returning undefined for an empty result.',[(Q,418,433,'host')])
    add('behavior','subdomain-ip-offset','subdomains','How does req.subdomains handle an IP hostname versus a domain and a custom offset?','Missing hostname yields []; IPs become a one-element array, domains are split and reversed, then sliced by subdomain offset.',[(Q,383,395,'subdomains')])
    add('behavior','accept-quality-params','accept-params','How does acceptParams distinguish quality q from other semicolon parameters?','It initializes quality to 1, sets q via parseFloat, and stores other keys in params, skipping malformed separators.',[(U,89,120,'acceptParams')])
    add('behavior','view-root-order','view-lookup','How are multiple view roots searched by View.lookup?','root is converted to an array; roots are traversed in order until resolve returns a path, then the loop stops.',[(V,104,123,'lookup')])
    add('behavior','json-html-escape','json-stringify','What characters does stringify escape with json escape enabled?','For a string result it replaces <, > and & with \\u003c, \\u003e and \\u0026; non-string results are left unchanged.',[(R,1025,1049,'stringify')])
    add('behavior','render-local-precedence','render-locals','Which locals win when app.render merges application locals, response locals and explicit options?','The spread order is this.locals, opts._locals, opts, so explicit options override response locals, which override app locals.',[(A,522,547,'render')])
    # Twelve architecture facets with concrete state or dependency ownership.
    add('architecture/facets','request-response-node-base','node-prototypes','Which Node prototypes underlie the Express request and response exports?','request exports an object created from http.IncomingMessage.prototype; response exports one from http.ServerResponse.prototype.',[(Q,19,35,'req'),(R,20,44,'res')])
    add('architecture/facets','body-parser-export-boundary','body-parser-boundary','Does the factory module implement its body parsers or expose dependency middleware?','It imports body-parser and exports its json, raw, text and urlencoded functions; no parser implementations are admitted here.',[(E,15,21,'bodyParser'),(E,77,81,'exports.json')])
    add('architecture/facets','request-response-crossrefs','dispatch-state','Which references and prototype objects are installed on each dispatched request/response pair?','handle sets req.res and res.req, sets their prototypes to this.request/this.response, initializes null-prototype res.locals only if absent, then dispatches.',[(A,152,177,'handle')])
    add('architecture/facets','app-state-null-prototypes','app-state','Which per-app dictionaries use null prototypes during initialization and default configuration?','cache, engines and settings are initialized with Object.create(null); locals is too and points locals.settings at settings.',[(A,59,66,'init'),(A,125,142,'defaultConfiguration')])
    add('architecture/facets','mount-wrapper-restoration','mount-wrapper','How does mounted_app restore the parent request/response environment after a child finishes?','It remembers req.app, calls child.handle, then sets req and res prototypes to the original app request/response and calls next(err).',[(A,221,240,'use')])
    add('architecture/facets','view-engine-cache-ownership','view-engine-cache','What cache holds loaded template engine functions and how does View populate it?','opts.engines keyed by extension holds engine callbacks; if absent View loads require(mod).__express, validates it and stores it; this.engine references that entry.',[(V,52,95,'View')])
    add('architecture/facets','render-view-cache-ownership','view-cache','How does app.render decide whether to reuse or populate the named View cache?','It derives renderOptions.cache from the view cache setting only when null; true checks cache[name] and stores successfully resolved new Views there.',[(A,522,575,'render')])
    add('architecture/facets','node-server-listen','http-server','What server does app.listen create and how does it route the callback on listen errors?','http.createServer(this) uses the callable app; a final function argument is wrapped in once and registered on error before server.listen applies arguments.',[(A,598,607,'listen')])
    add('architecture/facets','sendfile-event-lifecycle','file-stream-state','What event-driven state prevents sendfile completion from calling its callback twice?','The helper tracks done and streaming; directory/end/error handlers guard done, onfinish schedules a completion or abort decision, and file streams are piped into the response.',[(R,923,1011,'sendfile')])
    add('architecture/facets','external-negotiation-owner','accept-negotiation','How is request content negotiation separated from Express wrappers?','req.accepts and acceptsEncodings call methods on accepts(this), and charset/language wrappers forward rest arguments; actual negotiation is in external accepts.',[(Q,16,16,'accepts'),(Q,127,143,'accepts'),(Q,171,187,'acceptsCharsets')])
    add('architecture/facets','http-method-source','http-methods','Where do the methods used for dynamic application verbs originate?','utils imports Node http.METHODS and lowercases them; application imports methods and constructs methods on app through methods.forEach.',[(U,15,29,'methods'),(A,21,21,'methods'),(A,471,482,'methods.forEach')])
    add('architecture/facets','render-error-wrapper','view-render-errors','Which wrapper converts synchronously thrown view.render exceptions into callback errors?','tryRender calls view.render in try/catch and calls callback(err) on a thrown error; app.render invokes this wrapper.',[(A,573,575,'render'),(A,625,631,'tryRender')])
    # Sixteen cross-file data/call paths, distinct from the first four.
    add('crossfile-chain','app-call-to-dispatch','application-creation','Trace the callable application function into request dispatch.','createApplication defines a function calling app.handle(req,res,next); handle initializes response/request state and invokes this.router.handle.',[(E,36,39,'createApplication'),(A,152,177,'handle')],['callable app -> app.handle','app.handle -> router.handle (external boundary)'])
    add('crossfile-chain','default-subdomain-offset','subdomains','Trace the default subdomain offset into the request subdomains result.','defaultConfiguration sets subdomain offset to 2; subdomains reads it and slices the reversed domain labels or IP array.',[(A,90,100,'defaultConfiguration'),(Q,383,395,'subdomains')],['defaultConfiguration -> settings[subdomain offset]','subdomains -> app.get(subdomain offset)'])
    add('crossfile-chain','json-settings-serialization','json-stringify','Trace res.json from serialization settings to its response body.','json reads json escape/replacer/spaces, passes them to stringify, sets application/json if needed and sends the serialized body.',[(A,351,360,'set'),(R,236,252,'json'),(R,1025,1049,'stringify'),(R,126,164,'send')],['app.set -> json serialization settings','json -> stringify','json -> send'])
    add('crossfile-chain','jsonp-config-query','jsonp','Trace the configured JSONP parameter name to the callback value.','defaultConfiguration sets jsonp callback name to callback; jsonp reads that setting and indexes req.query, whose getter uses the configured parser.',[(A,136,142,'defaultConfiguration'),(R,264,286,'jsonp'),(Q,230,243,'query')],['defaultConfiguration -> jsonp callback name','jsonp -> req.query[app.get(jsonp callback name)]','query -> query parser fn'])
    add('crossfile-chain','freshness-response-feedback','freshness','Trace how response headers feed request freshness and alter res.send status.','send checks req.fresh; fresh accepts GET, HEAD or QUERY and 2xx/304 statuses, then calls fresh with request headers and response ETag/Last-Modified. A fresh request changes status to 304.',[(R,195,204,'send'),(Q,469,486,'fresh')],['send -> req.fresh','fresh -> res.get(ETag/Last-Modified)','send -> status(304)'])
    add('crossfile-chain','stale-fresh-inversion','freshness','Trace req.stale to the predicate deciding HTTP freshness.','stale negates fresh; fresh checks method/status before delegating matching to external fresh with response ETag and Last-Modified.',[(Q,497,499,'stale'),(Q,469,486,'fresh'),(R,701,703,'get')],['stale -> fresh','fresh -> res.get'])
    add('crossfile-chain','protocol-secure-derivation','proxy-trust','Trace req.secure through protocol and the trust proxy compiler.','secure compares protocol with https; protocol initially uses socket.encrypted and consults trust at hop 0 before a forwarded header; compileTrust provides the configured trust function.',[(Q,326,328,'secure'),(Q,297,314,'protocol'),(A,368,378,'set'),(U,194,214,'compileTrust')],['secure -> protocol','protocol -> trust proxy fn','app.set -> compileTrust'])
    add('crossfile-chain','host-hostname-subdomains','hostname','Trace req.subdomains through host and hostname for a port-bearing host header.','subdomains uses hostname; hostname reads host and removes the port outside an IPv6 bracket; host chooses forwarded versus direct Host according to trust.',[(A,370,378,'set'),(U,194,214,'compileTrust'),(Q,383,395,'subdomains'),(Q,444,459,'hostname'),(Q,418,433,'host')],['app.set -> compileTrust','subdomains -> hostname','hostname -> host','host -> trust proxy fn'])
    add('crossfile-chain','format-normalization','format','Trace res.format offered extensions to the selected Content-Type or 406 types list.','format negotiates keys with req.accepts, uses normalizeType(key).value on selection and normalizeTypes(keys) for error types; normalization delegates MIME extension lookup or parameter parsing.',[(R,573,598,'format'),(Q,127,130,'accepts'),(U,61,77,'normalizeType')],['format -> req.accepts','format -> normalizeType','format -> normalizeTypes'])
    add('crossfile-chain','string-send-charset','charset','Trace how res.send changes an existing string Content-Type charset.','For a string chunk with string Content-Type, send calls setCharset(type,utf-8), which parses and formats the header, then sets it through res.set.',[(R,134,147,'send'),(U,225,237,'setCharset'),(R,669,692,'header')],['send -> setCharset','send -> set(Content-Type)'])
    add('crossfile-chain','render-default-response-flow','render-default-callback','Trace a res.render call without an explicit callback through template rendering back to response completion.','res.render supplies a done callback: errors call req.next(err), success calls self.send(str). app.render forwards done through tryRender to view.render, which invokes the engine and normalizes sync completion.',[(R,896,920,'render'),(A,573,575,'render'),(A,625,631,'tryRender'),(V,133,159,'render')],['res.render -> app.render(done)','app.render -> tryRender','tryRender -> view.render','view.render -> done -> self.send or req.next'])
    add('crossfile-chain','render-response-locals','render-locals','Trace response locals from request dispatch through res.render into app.render options.','handle initializes res.locals if absent; res.render sets opts._locals to self.locals; app.render spreads those between app locals and explicit options.',[(A,170,177,'handle'),(R,896,920,'render'),(A,522,542,'render')],['handle -> res.locals','res.render -> opts._locals','app.render -> merged renderOptions'])
    add('crossfile-chain','verb-route-delegation','route-registration','Trace a dynamically installed HTTP verb call from the Node method list to route registration.','utils lowercases Node methods; application loops over them, obtains this.route(path) and applies callbacks on the route; app.route delegates to router.route.',[(U,15,29,'methods'),(A,471,482,'methods.forEach'),(A,256,258,'route')],['utils.methods -> app[method]','app[method] -> app.route','app.route -> router.route'])
    add('crossfile-chain','file-transfer-etag-switch','file-transfer','Trace the application etag setting used by res.sendFile rather than the compiled body generator.','sendFile sets opts.etag from this.app.enabled(etag); enabled Boolean-coerces set(setting), whose one-argument branch reads settings. This is a boolean file-transfer option; it does not invoke etag fn.',[(R,400,405,'sendFile'),(A,420,422,'enabled'),(A,351,355,'set')],['sendFile -> app.enabled(etag)','enabled -> app.set(setting)','set -> settings[setting]'])
    add('crossfile-chain','proxy-client-ip','proxy-ip','Trace trust proxy from application settings to req.ip.','set compiles trust proxy fn via compileTrust; ip reads that function and calls proxyaddr(this,trust), delegating client address computation.',[(A,368,378,'set'),(U,194,214,'compileTrust'),(Q,340,343,'ip')],['app.set -> compileTrust','ip -> trust proxy fn','ip -> proxyaddr'])
    add('crossfile-chain','default-error-dispatch','dispatch-errors','Trace the default final-handler error callback from the callable app to environment-dependent logging.','The callable app forwards next into handle. Without a callback, handle creates finalhandler with env and logerror bound to the app; logerror suppresses console.error only when env is test.',[(E,36,39,'createApplication'),(A,152,157,'handle'),(A,615,618,'logerror')],['callable app -> handle callback','handle -> finalhandler onerror(logerror.bind(this))','logerror -> app.get(env)'])
    # Eight configuration/error outcomes.
    add('config/error','invalid-query-parser-setting','query-parser','How is an unsupported query parser setting rejected?','compileQueryParser throws TypeError with unknown value for query parser function followed by the value.',[(U,162,183,'compileQueryParser')])
    add('config/error','empty-use-callbacks','middleware','What happens when app.use has no middleware after argument flattening?','It throws TypeError app.use() requires a middleware function before accessing the router.',[(A,190,218,'use')])
    add('config/error','missing-view-engine','view-engine','Which error occurs when constructing a View without an extension or default engine?','View throws Error No default engine was specified and no extension was provided.',[(V,52,63,'View')])
    add('config/error','invalid-required-engine-export','view-engine-cache','What happens if a required template module lacks a function-valued __express export?','View throws Error Module "<module>" does not provide a view engine. It does not cache that invalid value.',[(V,77,90,'View')])
    add('config/error','failed-view-lookup','view-lookup','How does app.render report a missing view file?','It creates Failed to lookup view "name" in views ... with formatted directory information, attaches err.view and calls done(err).',[(A,558,565,'render')])
    add('config/error','signed-cookie-secret','cookies','What prerequisite fails when res.cookie is called with signed:true but no request secret?','It throws Error cookieParser("secret") required for signed cookies before serializing the value.',[(R,747,759,'cookie')])
    add('config/error','content-type-array','response-headers','Which response header value rejects an array despite generic header array support?','res.header/res.set throws TypeError Content-Type cannot be set to an Array for a content-type field.',[(R,669,692,'header')])
    add('config/error','production-view-cache-default','view-cache','Which environment enables view caching by default?','defaultConfiguration reads NODE_ENV or development; only env===production enables view cache.',[(A,90,99,'defaultConfiguration'),(A,136,142,'defaultConfiguration')])
    # Twelve bounded hard negatives, including unsupported historic APIs and
    # plausible but false semantic expectations with positive corrective gold.
    add('hardnegative/noanswer','no-req-param-api','removed-param','Within admitted core request APIs, which implementation provides the historical req.param(name,defaultValue) body/query/route fallback?','No req.param implementation is defined. app.param registers route parameter callbacks and is not a request-value fallback API.',[(Q,63,85,'header'),(Q,230,243,'query'),(A,322,336,'param')],absence={'absent':'req.param fallback API','boundary':'removed historic API, not app.param','tokens':['req.param =','req.param=','req.param = function']})
    add('hardnegative/noanswer','no-res-sendfile-lowercase','removed-sendfile','Within admitted response exports, where is the historical lowercase res.sendfile method defined?','No lowercase res.sendfile export is defined; res.sendFile is the current public method. The private sendfile helper does not install the historic method.',[(R,375,402,'sendFile'),(R,923,928,'sendfile')],absence={'absent':'lowercase res.sendfile public API','boundary':'private helper is not an exported response method','tokens':['res.sendfile =','res.sendfile=']})
    add('hardnegative/noanswer','no-app-del-alias','removed-del','Within admitted application exports, where does app.del alias the DELETE method?','No del alias is installed; the method loop uses lowercased Node HTTP methods, yielding delete rather than del.',[(A,471,482,'methods.forEach'),(U,15,29,'methods')],absence={'absent':'app.del alias','boundary':'dynamic method names are Node METHODS lowercased','tokens':['app.del =','app.del=']})
    add('hardnegative/noanswer','no-local-websocket-upgrade','websocket-boundary','Within admitted core, which code implements a WebSocket handshake and frame parser on HTTP upgrade?','None in scope. app.listen creates an HTTP server and registers listen error handling; it does not attach an upgrade/frame parser.',[(A,598,607,'listen')],absence={'absent':'WebSocket handshake/frame parser','boundary':'HTTP server exposure permits external upgrade handling','tokens':["'upgrade'",'Sec-WebSocket-Accept','WebSocket']})
    add('hardnegative/noanswer','no-local-jwt-auth','jwt-boundary','Within admitted core, where does middleware verify a JWT signature and attach verified claims?','No JWT verifier or built-in authorization middleware exists in this scope; app.use is the user middleware entry and cookie signing is a separate mechanism.',[(A,190,243,'use'),(R,747,783,'cookie')],absence={'absent':'JWT signature verification/claims middleware','boundary':'user-supplied auth middleware','tokens':['jwt.verify','jsonwebtoken','Authorization']})
    add('hardnegative/noanswer','no-multipart-parser','multipart-boundary','Within the admitted middleware exports, which implementation parses multipart file uploads?','No multipart parser is exported or implemented here. The listed body parsers are json/raw/text/urlencoded and static delegates externally.',[(E,77,81,'exports.json')],absence={'absent':'multipart file upload parser','boundary':'body-parser exports are not multipart upload implementation','tokens':['multipart','multer','busboy']})
    add('hardnegative/noanswer','no-sql-transaction-api','database-boundary','Within admitted core, which API opens a database transaction and commits or rolls it back for each request?','No database/transaction lifecycle is implemented. Application middleware dispatch is the extension boundary.',[(A,152,177,'handle')],absence={'absent':'database transaction lifecycle API','boundary':'external application middleware','tokens':['BEGIN TRANSACTION','rollback','COMMIT','sequelize']})
    add('hardnegative/noanswer','no-http2-listener','http2-boundary','Within admitted app.listen, where is an HTTP/2 secure server created and ALPN configured?','No HTTP/2 secure listener exists; listen calls Node http.createServer(this). External callers can create other servers around the app.',[(A,598,607,'listen')],absence={'absent':'HTTP/2 secure server and ALPN configuration','boundary':'Node HTTP createServer only in app.listen','tokens':['http2','createSecureServer','ALPNProtocols']})
    add('hardnegative/noanswer','no-built-in-compression','compression-boundary','Within admitted core, which middleware negotiates gzip or brotli and compresses outgoing bodies?','None in scope. send computes length/ETag and ends the response; it does not implement gzip/brotli negotiation or compression.',[(R,168,227,'send')],absence={'absent':'gzip/brotli response compression middleware','boundary':'external middleware','tokens':['gzip','brotli','createGzip','node:zlib']})
    add('hardnegative/noanswer','get-route-overload-trap','route-registration','Does app.get with a single string register a zero-callback GET route? Identify the actual branch.','No. In the dynamic verb wrapper, get with one argument returns this.set(path) as a setting read; registering a GET route takes the other branch.',[(A,471,482,'methods.forEach')])
    add('hardnegative/noanswer','send-number-status-trap','send-body-dispatch','Does res.send(201) use the historical numeric status-code shortcut at this SHA?','No. A numeric chunk enters the boolean/number/object branch and is forwarded to this.json(chunk); setting status requires the status API.',[(R,134,164,'send'),(R,65,78,'status')])
    add('hardnegative/noanswer','redirect-back-trap','redirect','Does res.location("back") read the request Referer at this SHA?','No. location simply encodes the supplied literal URL and sets Location. The request header alias implementation is separate and is not called here.',[(R,796,798,'location'),(Q,63,85,'header')])
